const e=[{target:"#solitaire",title:"Welcome to Solitaire",icon:"fal fa-spade",color:"#ff4757",content:"Welcome to Solitaire! A faithful recreation of the classic OS card game designed for quick mental breaks and focus reset.",placement:"right"},{target:"#sol-stock-pile",title:"1. The Stock Pile (Draw Deck)",icon:"fal fa-spade",color:"#ff4757",content:"Click the stock pile to draw cards into the waste pile. When empty, click to recycle the deck.",placement:"right"},{target:"#sol-tableau-container",title:"2. The Tableau Columns",icon:"fal fa-spade",color:"#ff4757",content:"Build columns down in alternating colors (Red King ➔ Black Queen ➔ Red Jack). You can move single cards or full stacks!",placement:"right"},{target:"#sol-foundation-container",title:"3. The Foundation Piles",icon:"fal fa-spade",color:"#ff4757",content:"Build up the 4 foundation piles by suit starting from Ace to King (Ace ➔ 2 ➔ 3 ... ➔ King). Double-click cards to auto-send them here!",placement:"right"},{target:"#sol-action-tools",title:"4. Hints & Restart",icon:"fal fa-spade",color:"#ff4757",content:"Need help? Click the lightbulb for a hint, or click the dice to deal a fresh hand.",placement:"right"},{target:()=>null,title:"Enjoy Your Passtime!",icon:"fal fa-spade",color:"#ff4757",content:"You're ready to play! Stack cards, clear the board, and enjoy your break."}];export{e as solitaireTourSteps};
